MM.mnemo[30] = {"cards":[{"id":"ko-k3-0485","w":"화장실","cs":"toaleta, záchod","en":"toilet; bathroom","p":"n","o":"s","ex":"지금 화장실에 누구 있어요?","exc":"Je teď někdo na záchodě?","h":"화장 = líčení (FAJN ŽANETA) + 실 = místnost: kde se líčíš = toaleta.","m":"化粧 líčení + 室 místnost = místnost na upravení se. V Koreji bývá záchod v koupelně.","r":["hwa-化","jang-粧","sil-室"]},{"id":"ko-k3-0486","w":"분장실","cs":"divadelní šatna; maskérna (v zákulisí)","en":"dressing room (backstage)","p":"n","o":"s","rz":["분장 + 실 = 분장실","분장 (jevištní líčení, maskování) + 실 (místnost) = maskérna, šatna v zákulisí"],"h":"PUN-DŽANG ≈ PUNK ŽANETA: punková maska v maskérně + 실 = místnost.","m":"扮 přestrojit se, líčit se + 粧 líčit se, zdobit + 室 místnost = místnost pro líčení herců v zákulisí, tedy maskérna nebo divadelní šatna.","r":["bun-扮","jang-粧","sil-室"]},{"id":"ko-k3-0487","w":"교실","cs":"třída; učebna","en":"classroom","p":"n","o":"s","rz":["교 + 실 = 교실","교 (učit, škola) + 실 (místnost) = třída, učebna"],"h":"KJO jako v 학교 (škola) + 실 = místnost: třída.","m":"敎 učit + 室 místnost = místnost, kde se učí, tedy třída nebo učebna. Kořen 室 (místnost) najdeš ve všech názvech místností této lekce.","r":["gyo-敎","sil-室"]},{"id":"ko-k3-0488","w":"연습실","cs":"zkušebna; cvičební místnost","en":"practice room","p":"n","o":"s","rz":["연습 + 실 = 연습실","연습 (cvičení, trénink) + 실 (místnost) = zkušebna"],"h":"연습 = cvičit (JONÁŠ SUPÍ) + 실 = místnost: zkušebna.","m":"練 trénovat + 習 cvičit + 室 místnost = místnost na trénování a zkoušení (třeba hudby nebo tance), tedy zkušebna. Samotné 연습 znamená ‚cvičení, zkouška‘.","r":["yeon-練","seup-習","sil-室"]},{"id":"ko-k3-0489","w":"대기실","cs":"čekárna","en":"waiting room","p":"n","o":"s","ex":"대기실에서 기다려 주세요.","exc":"Počkejte prosím v čekárně. (에서 → kde)","h":"TE-GI ≈ „TEĎ KÝVNI“: čekáš, až ti kývnou + 실 = místnost: čekárna.","m":"待 čekat + 機 příležitost, chvíle + 室 místnost = místnost, kde se čeká na svou chvíli, tedy čekárna. Samotné 대기 znamená ‚čekání, pohotovost‘.","r":["dae-待","gi-機","sil-室"]},{"id":"ko-k3-0490","w":"회의실","cs":"zasedací místnost; zasedačka; jednací místnost","en":"meeting room","p":"n","o":"s","ex":"회의실에서 봐요.","exc":"Uvidíme se v zasedačce. (에서 → kde)","h":"HWE-I ≈ HOVORY: místnost na hovory a porady + 실 = zasedačka.","m":"會 setkání + 議 projednávat, rada + 室 místnost = místnost pro schůze a porady, tedy zasedačka. Samotné 회의 znamená ‚schůze, porada‘.","r":["hoe-會","ui-議","sil-室"]},{"id":"ko-k3-0491","w":"병실","cs":"nemocniční pokoj","en":"hospital room, patient’s room","p":"n","o":"s","rz":["병 + 실 = 병실","병 (nemoc) + 실 (místnost) = nemocniční pokoj"],"h":"PJONG jako v 병원 (nemocnice) + 실 = místnost: nemocniční pokoj.","m":"病 nemoc + 室 místnost = pokoj pro nemocné v nemocnici. Stejné 病 najdeš i ve slově 병원 (nemocnice) nebo 병가 (nemocenská dovolená).","r":["byeong-病","sil-室"]},{"id":"ko-k3-0492","w":"미용실","cs":"kadeřnictví; kosmetický salon","en":"beauty parlor; hair salon","p":"n","o":"s","rz":["미용 + 실 = 미용실","미용 (péče o krásu, kosmetika) + 실 (místnost) = kadeřnictví, kosmetický salon"],"h":"MI-JONG ≈ MYJOU: myjou ti vlasy + 실 = místnost: kadeřnictví.","m":"美 krása + 容 vzhled, podoba + 室 místnost = salon krásy (v Koreji se tak běžně říká kadeřnictví). Stejné 美 je i ve slově 미술 (výtvarné umění).","r":["mi-美","yong-容","sil-室"]},{"id":"ko-k3-0493","w":"교무실","cs":"sborovna; kabinet učitelů","en":"teacher’s office","p":"n","o":"s","rz":["교 + 무 + 실 = 교무실","교 (učit, škola) + 무 (povinnost, agenda) + 실 (místnost) = sborovna"],"h":"KJO-MU ≈ „KDO MŮŽE?“: do sborovny můžou jen učitelé + 실 = místnost.","m":"敎 učit + 務 povinnost, agenda + 室 místnost = místnost pro školní agendu a učitele, tedy sborovna (podobně jako 사무실 je kancelář).","r":["gyo-敎","mu-務","sil-室"]},{"id":"ko-k3-0494","w":"실장","cs":"vedoucí oddělení; vedoucí kanceláře / provozu","en":"head of the office","p":"n","o":"s","rz":["실 + 장 = 실장","실 (místnost, oddělení) + 장 (vedoucí) = vedoucí oddělení"],"h":"실 = místnost + DŽANG ≈ DŽANGO, šéf (jako v 회장님): vedoucí oddělení.","m":"室 místnost, oddělení + 長 vedoucí, hlava = vedoucí oddělení nebo kanceláře (s uctivou koncovkou 실장님 se tak oslovuje i vedoucí provozovny či manažer).","r":["sil-室","jang-長"]},{"id":"ko-k3-0495","w":"실내","cs":"vnitřek; interiér; uvnitř (budovy)","en":"indoors","p":"n","o":"s","rz":["실 + 내 = 실내","실 (místnost) + 내 (uvnitř) = vnitřek, uvnitř"],"h":"실 = místnost + NE ≈ NE VEN: zůstaneš uvnitř.","m":"室 místnost + 內 uvnitř = vnitřní prostor, interiér (např. 실내 수영장 = krytý bazén). Opak: 실외 (室 místnost + 外 venek = venku, exteriér).","r":["sil-室","nae-內"]},{"id":"ko-k3-0496","w":"실외","cs":"venku, venkovní prostor","en":"outdoors, outside","p":"n","o":"s","rz":["실 + 외 = 실외","místnost + venek = venku"],"h":"실 + WE ≈ VEN: venku, venkovní prostor.","m":"室 místnost + 外 venek. Opak 실내 (uvnitř). 실외 수영장 = venkovní bazén.","r":["sil-室","oe-外"]},{"id":"ko-k3-0497","w":"침실","cs":"ložnice","en":"bedroom","p":"n","o":"s","ex":"침실에 거울이 두 개 있어요.","exc":"V ložnici jsou dvě zrcadla. (에 → kde; 이 → 1. pád)","h":"ČIM jako v 침대 (postel, ČIMČARÁRA) + 실 = místnost: ložnice.","m":"寢 spát + 室 místnost = místnost na spaní, tedy ložnice. Stejný kořen 寢 je i ve slově 침대 (postel).","r":["chim-寢","sil-室"]},{"id":"ko-k3-0498","w":"거실","cs":"obývací pokoj; obývák","en":"living room","p":"n","o":"s","ex":"집: 거실, 침실","exc":"domov: obývací pokoj, ložnice","h":"KO ≈ KOBEREC: velký koberec v obýváku + 실 = místnost.","m":"居 bydlet, pobývat + 室 místnost = hlavní místnost, kde se doma pobývá, tedy obývací pokoj. Stejné 居 najdeš i ve slově 주거 (bydlení).","r":["geo-居","sil-室"]},{"id":"ko-k3-0499","w":"응급실","cs":"pohotovost; urgentní příjem","en":"emergency room","p":"n","o":"s","ex":"병원: 수술실, 병실, 응급실","exc":"nemocnice: operační sál, nemocniční pokoj, pohotovost","h":"ŮNG-GŮP ≈ „ÚNG! GUP!“: houká sanitka + 실 = místnost: pohotovost.","m":"應 reagovat + 急 naléhavý + 室 místnost = místnost pro naléhavé případy, tedy lékařská pohotovost (urgentní příjem). Samotné 응급 znamená ‚naléhavý, první pomoc‘.","r":["eung-應","geup-急","sil-室"]},{"id":"ko-k3-0500","w":"조리실","cs":"kuchyňka; přípravna jídel (ve škole, restauraci, nemocnici)","en":"kitchen (not at home)","p":"n","o":"s","ex":"조리실 (調理室)","exc":"조리실 (přípravna jídel, kuchyňka)","h":"조리 = vaření (ČO-RI ≈ JIŘÍ, jako v 요리) + 실 = místnost: kuchyňka.","m":"調 připravovat, ladit + 理 upravit + 室 místnost = místnost pro přípravu pokrmů mimo domácnost (např. ve škole nebo firmě; domácí kuchyně je 부엌 nebo 주방).","r":["jo-調","ri-理","sil-室"]},{"id":"ko-k3-0501","w":"수술실","cs":"operační sál","en":"operating room","p":"n","o":"s","ex":"병원: 수술실, 병실, 응급실","exc":"nemocnice: operační sál, nemocniční pokoj, pohotovost","h":"SU-SUL ≈ „ŠUS-ŠUS“: šustí skalpel + 실 = místnost: operační sál.","m":"手 ruka + 術 technika, zákrok (수술 = operace) + 室 místnost = místnost pro chirurgické zákroky, tedy operační sál. Vazba: 수술을 받다 = podstoupit operaci.","r":["su-手","sul-術","sil-室"]},{"id":"ko-k3-0502","w":"강의실","cs":"posluchárna; přednáškový sál (na vysoké škole)","en":"lecture room (usually at a university)","p":"n","o":"s","ex":"학교: 교실, 강의실, 양호실, 교무실, 교장실","exc":"škola: třída, posluchárna, ošetřovna, sborovna, ředitelna","h":"강의 = přednáška (KANG-I ≈ KANGAROO: klokan přednáší) + 실 = místnost.","m":"講 přednášet + 義 význam (강의 = přednáška) + 室 místnost = místnost pro vysokoškolské přednášky, tedy posluchárna (na rozdíl od školní třídy 교실).","r":["gang-講","ui-義","sil-室"]},{"id":"ko-k3-0503","w":"휴게실","cs":"odpočívárna, místnost pro odpočinek","en":"break room, lounge","p":"n","o":"s","ex":"휴게실 (休憩室)","exc":"odpočívárna","h":"HJU-GE ≈ HUGO: Hugo si dal pauzu + 실 = místnost. Příbuzné 휴가 = dovolená.","m":"休 odpočinek + 憩 oddech + 室 místnost. Pozor na pravopis: 휴게실, ne 휴계실.","r":["hyu-休","ge-憩","sil-室"]},{"id":"ko-k3-0504","w":"양호실","cs":"školní ošetřovna; marodka","en":"school infirmary","p":"n","o":"s","ex":"학교: 교실, 강의실, 양호실, 교무실, 교장실","exc":"škola: … školní ošetřovna …","h":"JANG-HO ≈ JANKO: Janko leží na marodce + 실 = místnost.","m":"養 pečovat + 護 chránit, opatrovat + 室 místnost = místnost, kde se pečuje o zraněné nebo nemocné žáky, tedy školní ošetřovna (dnes se jí říká i 보건실).","r":["yang-養","ho-護","sil-室"]},{"id":"ko-k3-0505","w":"교장실","cs":"ředitelna (ve škole)","en":"principal’s office","p":"n","o":"s","ex":"학교: 교실, 강의실, 양호실, 교무실, 교장실","exc":"škola: … ředitelna","h":"교 jako v 학교 + 장 = šéf (jako v 실장) = ředitel + 실 = místnost: ředitelna.","m":"校 škola + 長 vedoucí, hlava (교장 = ředitel školy) + 室 místnost = kancelář ředitele školy, tedy ředitelna.","r":["gyo-校","jang-長","sil-室"]},{"id":"ko-k3-0506","w":"오락실","cs":"videoherna; herna s automaty","en":"video arcade","p":"n","o":"s","ex":"오락실 (娛樂室)","exc":"오락실 (videoherna)","h":"O-RAK ≈ O RAKETY: hraješ na automatu o rakety + 실 = místnost: herna.","m":"娛 bavit se + 樂 radost, zábava (오락 = zábava) + 室 místnost = místnost pro zábavu, tedy herna s videohrami a arkádovými automaty.","r":["o-娛","rak-樂","sil-室"]},{"id":"ko-k3-0507","w":"흡연실","cs":"kuřárna; místnost pro kuřáky","en":"smoking room","p":"n","o":"s","ex":"흡연실 (吸煙室)","exc":"흡연실 (kuřárna)","h":"HŮP-JON ≈ HUBA, JONÁŠ: Jonáš si strčí do huby cigaretu + 실 = místnost: kuřárna.","m":"吸 vdechovat, nasávat + 煙 kouř, dým + 室 místnost = místnost pro vdechování kouře, tedy kuřárna. Vyslovuje se [흐변실]. Opak: 금연실 (nekuřácká místnost).","r":["heup-吸","yeon-煙","sil-室"]}],"gram":{"id":"ko-k3-g30","w":"실 (室)","en":"Word Builder 2","cs":"slovotvorný kořen 실 (室) – místnost, pokoj, sál","vy":"Sinokorejský kořen 실 (室) znamená ‚místnost, pokoj, sál‘ nebo ‚kancelář‘. Nejčastěji stojí na konci složených podstatných jmen a určuje konkrétní účelové místnosti ve škole, nemocnici, firmě nebo doma (např. 교실, 화장실, 회의실, 거실). Na začátku slova se objevuje například ve výrazech 실내 (interiér, uvnitř) nebo 실장 (vedoucí oddělení či kanceláře).","m":"Slabika 실 (室) tvoří oficiálnější či účelové názvy místností (화장실 = toaleta, 거실 = obývák, 수술실 = operační sál), zatímco 방 (房) se používá spíš pro běžné obytné pokoje nebo podniky (내 방 = můj pokoj, PC방 = internetová herna).","s":[["실 (室)","kořen 실 (室) souvisí s ‚místností‘ nebo ‚pokojem‘"],["화장 + 실 = 화장실","líčení/úprava + místnost = toaleta, koupelna"],["분장 + 실 = 분장실","divadelní líčení + místnost = šatna (v divadle, zákulisí)"],["교 + 실 = 교실","učit/škola + místnost = učebna, třída"],["대기 + 실 = 대기실","čekání + místnost = čekárna"],["회 + 의 + 실 = 회의실","setkání + jednání + místnost = zasedací místnost, konferenční sál"],["사 + 무 + 실 = 사무실","věc/práce + úkol + místnost = kancelář"],["실 + 장 = 실장","místnost/oddělení + vedoucí = vedoucí oddělení / šéf kanceláře"],["실 + 내 = 실내 · 실 + 외 = 실외","vnitřek (interiér) · venek (exteriér)"],["면접은 어디에서 봐요?","Kde probíhá ten pohovor?"],["회의실에서 봐요. 대기실에서 기다려 주세요.","V zasedací místnosti. Počkejte prosím v čekárně."],["네, 알겠습니다.","Dobře, rozumím."],["지금 화장실에 누구 있어요?","Je teď někdo na záchodě?"],["침실에 거울이 두 개 있어요.","V ložnici jsou dvě zrcadla."],["사무실에서 이상한 냄새가 나요.","V kanceláři je cítit nějaký divný zápach."],["학교: 교실 · 강의실 · 양호실 · 교무실 · 교장실","škola: učebna · přednáškový sál · ošetřovna · sborovna · ředitelna"],["병원: 수술실 · 병실 · 응급실 / 집: 거실 · 침실 / 회사: 사무실 · 회의실","nemocnice: operační sál · nemocniční pokoj · pohotovost / domov: obývák · ložnice / firma: kancelář · zasedačka"]]}};
